<?php
declare(strict_types=1);
namespace App\Application\QuestionLearning\Service;
use App\Application\QuestionLearning\DTO\Request\UpdateQuestionInteractionRequestDto;use App\Application\QuestionLearning\DTO\Response\QuestionInteractionResponseDto;use App\Application\QuestionLearning\Mapper\QuestionInteractionResponseMapper;use App\Domain\QuestionBank\Repository\FrozenQuestionReaderInterface;use App\Domain\QuestionLearning\Entity\LearningEvent;use App\Domain\QuestionLearning\Entity\UserQuestionInteraction;use App\Domain\QuestionLearning\Enum\LearningEventType;use App\Domain\QuestionLearning\Repository\CompletedAttemptLearningSignalReaderInterface;use App\Domain\QuestionLearning\Repository\LearningEventRepositoryInterface;use App\Domain\QuestionLearning\Repository\UserQuestionInteractionRepositoryInterface;use App\Domain\QuestionLearning\ValueObject\QuestionInteractionState;
final readonly class UpdateQuestionInteractionService { public function __construct(private FrozenQuestionReaderInterface $questions, private UserQuestionInteractionRepositoryInterface $interactions, private QuestionInteractionResponseMapper $mapper, private ?CompletedAttemptLearningSignalReaderInterface $subjects = null, private ?LearningEventRepositoryInterface $events = null) {} public function execute(string $userId, UpdateQuestionInteractionRequestDto $request, \DateTimeImmutable $now): QuestionInteractionResponseDto { if (count($this->questions->findByIds([$request->questionId])) !== 1) { throw new \DomainException('Questão não encontrada.'); } $interaction = $this->interactions->find($userId, $request->questionId) ?? new UserQuestionInteraction($userId, $request->questionId, new QuestionInteractionState(false, false, false), $now, $now); $current = $interaction->state(); $next = new QuestionInteractionState($request->favorite ?? $current->favorite, $request->reviewLater ?? $current->reviewLater, $request->notMastered ?? $current->notMastered); $interaction->update($next, $now); $this->interactions->save($interaction); if ($next->notMastered !== $current->notMastered && $this->subjects !== null && $this->events !== null) { $type = $next->notMastered ? LearningEventType::NOT_MASTERED_ENABLED : LearningEventType::NOT_MASTERED_DISABLED; $subjectIds = $this->subjects->taxonomySubjectIdsForQuestion($request->questionId); foreach ($subjectIds === [] ? [null] : $subjectIds as $subjectId) { $this->events->append(new LearningEvent($this->uuid(), $userId, $request->questionId, null, $subjectId, $type, null, null, 'QUESTION_INTERACTION', [], $now)); } } return $this->mapper->toResponse($interaction); } private function uuid(): string { $bytes = random_bytes(16); $bytes[6] = chr((ord($bytes[6]) & 15) | 64); $bytes[8] = chr((ord($bytes[8]) & 63) | 128); return vsprintf('%s%s-%s-%s-%s-%s%s%s', str_split(bin2hex($bytes), 4)); } }
